const total = ctx.words.length;
const latest = Math.max(ctx.duration - 0.6, 0);
const cue = (fraction) => Math.min(ctx.at(Math.min(Math.round(fraction * (total - 1)), total - 1)), latest);
const wordsFrom = (start, count) => ctx.words.slice(start, start + count).map((word) => word.text).join(" ");
const clean = (text, limit) => text.replace(/[^\p{L}\p{N}]/gu, "").slice(0, limit);
const SHAPES = [
  { shape: "wide", ratio: "16:9", first: 4 },
  { shape: "tall", ratio: "9:16", first: 5 },
  { shape: "square", ratio: "1:1", first: 6 },
];
const shell = document.createElement("div");
shell.className = "mo-r-shell";
const title = document.createElement("h1");
title.className = "mo-r-title";
title.textContent = wordsFrom(0, 4);
const cards = document.createElement("div");
cards.className = "mo-r-cards";
const nodes = SHAPES.map((item) => {
  const card = document.createElement("div");
  card.className = "mo-card mo-r-card";
  const slot = document.createElement("div");
  slot.className = "mo-r-slot";
  const glyph = document.createElement("div");
  glyph.className = "mo-r-glyph mo-r-" + item.shape;
  slot.append(glyph);
  const text = document.createElement("div");
  const name = document.createElement("p");
  name.className = "mo-r-name";
  name.textContent = clean(ctx.words[Math.min(item.first, total - 1)].text, 10) || item.shape;
  const ratio = document.createElement("p");
  ratio.className = "mo-caption mo-r-ratio";
  ratio.textContent = item.ratio;
  text.append(name, ratio);
  card.append(slot, text);
  cards.append(card);
  return card;
});
shell.append(title, cards);
ctx.root.append(shell);
const portrait = ctx.aspect === "9:16";
ctx.timeline.from(title, { opacity: 0, y: 36, duration: 0.6, ease: "power3.out" }, 0.1);
nodes.forEach((card, index) => {
  ctx.timeline.from(
    card,
    { opacity: 0, x: portrait ? -60 : 0, y: portrait ? 0 : 50, duration: 0.55, ease: "power3.out" },
    cue(0.3 + index * 0.25),
  );
});

