.mo-s-{{sceneId}} {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.mo-s-{{sceneId}} .mo-r-shell {
  display: flex;
  flex-direction: column;
  gap: calc(var(--mo-unit) * 4);
  width: 100%;
  align-items: center;
}
.mo-s-{{sceneId}} .mo-r-title {
  margin: 0;
  max-width: 100%;
  font-size: var(--mo-text-subtitle);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.03em;
  text-align: center;
}
.mo-s-{{sceneId}} .mo-r-cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: calc(var(--mo-unit) * 2.4);
  width: 100%;
}
.mo-s-{{sceneId}} .mo-r-card {
  display: flex;
  flex-direction: column;
  gap: calc(var(--mo-unit) * 2);
  align-items: center;
  padding: calc(var(--mo-unit) * 2.4);
  text-align: center;
}
.mo-s-{{sceneId}} .mo-r-slot {
  display: flex;
  width: calc(var(--mo-unit) * 14);
  height: calc(var(--mo-unit) * 14);
  align-items: center;
  justify-content: center;
}
.mo-s-{{sceneId}} .mo-r-glyph {
  flex: none;
  border: calc(var(--mo-unit) * 0.4) solid var(--mo-accent);
  border-radius: calc(var(--mo-unit) * 0.8);
  background: var(--mo-elevated);
}
.mo-s-{{sceneId}} .mo-r-wide {
  width: calc(var(--mo-unit) * 14);
  aspect-ratio: 16 / 9;
}
.mo-s-{{sceneId}} .mo-r-tall {
  height: calc(var(--mo-unit) * 14);
  aspect-ratio: 9 / 16;
}
.mo-s-{{sceneId}} .mo-r-square {
  width: calc(var(--mo-unit) * 10);
  aspect-ratio: 1;
}
.mo-s-{{sceneId}} .mo-r-name {
  margin: 0;
  font-size: var(--mo-text-body);
  font-weight: 700;
}
.mo-s-{{sceneId}} .mo-r-ratio {
  font-family: var(--mo-font-mono);
}
@container stage (aspect-ratio < 1) {
  .mo-s-{{sceneId}} .mo-r-cards {
    grid-template-columns: minmax(0, 1fr);
  }
  .mo-s-{{sceneId}} .mo-r-card {
    flex-direction: row;
    justify-content: flex-start;
    gap: calc(var(--mo-unit) * 3);
    text-align: left;
  }
  .mo-s-{{sceneId}} .mo-r-slot {
    width: calc(var(--mo-unit) * 14);
    height: calc(var(--mo-unit) * 10);
  }
  .mo-s-{{sceneId}} .mo-r-tall {
    height: calc(var(--mo-unit) * 10);
  }
  .mo-s-{{sceneId}} .mo-r-square {
    width: calc(var(--mo-unit) * 8);
  }
  .mo-s-{{sceneId}} .mo-r-wide {
    width: calc(var(--mo-unit) * 13);
  }
}
